package com.gamingevents.controller;
import com.gamingevents.dto.TournamentDtos.*; import com.gamingevents.service.TournamentService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/tournaments") public class TournamentController { final TournamentService s; public TournamentController(TournamentService x){s=x;} @GetMapping public List<Response> list(@RequestParam(required=false) String search){return s.list(search);} @GetMapping("/{id}") public Response get(@PathVariable Long id){return s.get(id);} @PostMapping @PreAuthorize("hasAnyRole('ORGANIZER','ADMIN')") public Response create(@Valid @RequestBody Request r,Authentication a){return s.create(r,a.getName());} @PutMapping("/{id}") @PreAuthorize("hasRole('ORGANIZER')") public Response update(@PathVariable Long id,@Valid @RequestBody Request r,Authentication a){return s.update(id,r,a.getName());} @DeleteMapping("/{id}") @PreAuthorize("hasRole('ORGANIZER')") public void delete(@PathVariable Long id,Authentication a){s.delete(id,a.getName());} @PostMapping("/{id}/join") @PreAuthorize("hasRole('PLAYER')") public void join(@PathVariable Long id,Authentication a){s.join(id,a.getName());}}
